<?php
declare(strict_types=1);

require_once __DIR__ . '/../includes/order-helpers.php';
require_admin();

$stats = [
    'pets' => (int) (db_value('SELECT COUNT(*) FROM pets') ?? 0),
    'available' => (int) (db_value("SELECT COUNT(*) FROM pets WHERE status = 'Available'") ?? 0),
    'pending' => (int) (db_value("SELECT COUNT(*) FROM pets WHERE status = 'Pending'") ?? 0),
    'adopted' => (int) (db_value("SELECT COUNT(*) FROM pets WHERE status = 'Adopted'") ?? 0),
    'applications' => (int) (db_value("SELECT COUNT(*) FROM adoption_applications WHERE status = 'SUBMITTED'") ?? 0),
    'approved' => (int) (db_value("SELECT COUNT(*) FROM adoption_applications WHERE status = 'APPROVED'") ?? 0),
    'users' => (int) (db_value("SELECT COUNT(*) FROM users WHERE role = 'USER'") ?? 0),
    'waiting' => (int) (db_value('SELECT COUNT(*) FROM waiting_list') ?? 0),
    'orders' => (int) (db_value('SELECT COUNT(*) FROM orders') ?? 0),
    'revenue' => (float) (db_value("SELECT COALESCE(SUM(total), 0) FROM orders WHERE payment_status = 'PAID' AND status <> 'CANCELLED'") ?? 0),
];
$orderCounts = admin_order_counts();
$recentOrders = admin_orders([], 5, 0);
$species = db_all('SELECT species, COUNT(*) AS total FROM pets GROUP BY species ORDER BY total DESC');
$logs = db_all('SELECT al.*, u.name AS admin_name FROM admin_logs al JOIN users u ON u.id = al.admin_id ORDER BY al.created_at DESC LIMIT 5');
$pendingApplications = db_all("SELECT a.*, p.name AS pet_name, u.name AS applicant FROM adoption_applications a JOIN pets p ON p.id = a.pet_id JOIN users u ON u.id = a.user_id WHERE a.status IN ('SUBMITTED', 'UNDER REVIEW', 'INTERVIEW') ORDER BY a.created_at DESC LIMIT 5");
$maxSpecies = max(1, ...array_map(static fn (array $row): int => (int) $row['total'], $species ?: [['total' => 1]]));
$adminSection = 'dashboard';
$pageTitle = 'Admin dashboard';
$bodyClass = 'dashboard-page admin-page';
require __DIR__ . '/../includes/header.php';
?>
