['order_reference']) ?></a></td><td><?= e($recentOrder['user_name']) ?></td><td><?= status_badge((string) $recentOrder['status']) ?></td><td><?= payment_status_badge((string) $recentOrder['payment_status']) ?></td><td><?= e(format_money((float) $recentOrder['total'])) ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p class="text-muted mb-0">No shop orders yet.</p><?php endif; ?></section></div><div class="col-12"><section class="dashboard-panel"><div class="d-flex justify-content-between align-items-center mb-3"><div><span class="eyebrow">Audit trail</span><h2 class="mt-2 mb-0">Recent admin activity</h2></div><a class="small" href="<?= e(app_url('admin/reports.php')) ?>">View all reports <i class="bi bi-arrow-right" aria-hidden="true"></i></a></div><?php if ($logs): ?><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Admin</th><th>Action</th><th>Description</th><th>When</th></tr></thead><tbody><?php foreach ($logs as $log): ?><tr><td><?= e($log['admin_name']) ?></td><td><span class="admin-badge"><?= e($log['action']) ?></span></td><td><?= e($log['description']) ?></td><td><small class="text-muted"><?= e(format_date($log['created_at'], 'M j, Y · g:i A')) ?></small></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p class="small text-muted mb-0">No activity recorded yet.</p><?php endif; ?></section></div></div></div></div>
